# Run this in Kimi Code CLI to find, audit, fix Deepgram

$targetPath = "C:\Users\Dekan AI Brother\Projects"
$deepgramFiles = @()

Write-Host "=== HUNTING DEEPGRAM ===" -ForegroundColor Cyan

